"use client";

import { useState, useEffect } from "react";
import { Alert, Box, Slide } from "@mui/material";

export type ToastEventDetail = {
  message: string;
  severity: "success" | "error" | "warning" | "info";
};

type ToastItem = {
  id: string;
  message: string;
  severity: "success" | "error" | "warning" | "info";
};

export function showToast(
  message: string,
  severity: "success" | "error" | "warning" | "info" = "success"
) {
  if (typeof window !== "undefined") {
    window.dispatchEvent(
      new CustomEvent("finter-notification", {
        detail: { message, severity },
      })
    );
  }
}

export default function ToastNotification() {
  const [toasts, setToasts] = useState<ToastItem[]>([]);

  useEffect(() => {
    const handleNotification = (e: Event) => {
      const customEvent = e as CustomEvent<ToastEventDetail>;
      if (customEvent.detail) {
        const newToast: ToastItem = {
          id: Math.random().toString(36).substring(2, 9),
          message: customEvent.detail.message,
          severity: customEvent.detail.severity || "success",
        };
        setToasts((prev) => [...prev, newToast]);

        setTimeout(() => {
          setToasts((prev) => prev.filter((t) => t.id !== newToast.id));
        }, 4000);
      }
    };

    window.addEventListener("finter-notification", handleNotification);
    return () => {
      window.removeEventListener("finter-notification", handleNotification);
    };
  }, []);

  const handleClose = (id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  return (
    <Box
      sx={{
        position: "fixed",
        top: 24,
        left: "50%",
        transform: "translateX(-50%)",
        zIndex: 10000,
        display: "flex",
        flexDirection: "column",
        gap: 1.25,
        alignItems: "center",
        pointerEvents: "none",
        width: "100%",
        maxWidth: "480px",
        px: 2,
      }}
    >
      {toasts.map((toast) => (
        <Slide key={toast.id} direction="down" in={true} mountOnEnter unmountOnExit>
          <Box sx={{ pointerEvents: "auto", width: "100%" }}>
            <Alert
              onClose={() => handleClose(toast.id)}
              severity={toast.severity}
              variant="filled"
              sx={{
                borderRadius: "14px",
                fontSize: "0.8125rem",
                fontWeight: 600,
                boxShadow: "0 10px 30px rgba(0, 0, 0, 0.4)",
                backgroundColor:
                  toast.severity === "success"
                    ? "#10b981 !important"
                    : toast.severity === "error"
                    ? "#ef4444 !important"
                    : toast.severity === "warning"
                    ? "#f59e0b !important"
                    : "#3b82f6 !important",
                color: "#ffffff !important",
                "& .MuiAlert-icon": {
                  color: "#ffffff !important",
                },
                "& .MuiAlert-action svg": {
                  color: "#ffffff !important",
                },
              }}
            >
              {toast.message}
            </Alert>
          </Box>
        </Slide>
      ))}
    </Box>
  );
}
